"""Pre-rendered disclaimer glyphs. Generated from WenQuanYi Micro Hei.

The pixels are the Chinese sentence required on every redraw. Runtime does not
need Pillow or a font file.
"""

from __future__ import annotations

import base64
import zlib

WIDTH = 294
HEIGHT = 30
_BLOB = """

"""


def disclaimer_rgb() -> bytes:
    raw = zlib.decompress(base64.b64decode("".join(_BLOB.split())))
    if len(raw) != WIDTH * HEIGHT * 3:
        raise RuntimeError("disclaimer bitmap size mismatch")
    return raw
